export function getIconForLanguageExtension(language: string) {
  switch (language) {
    case "json":
    case "jsonc":
    case "json5":
      return <Icons.json />
    case "ico":
      return <Icons.ico />
    case "svg":
      return <Icons.svg />
    case "mjs":
    case "cjs":
    case "js":
      return <Icons.js />
    case "css":
      return <Icons.css />
    case "gitignore":
      return <Icons.gitignore />
    case "ts":
    case "mts":
    case "cts":
    case "typescript":
      return <Icons.ts />
    case "jsx":
    case "tsx":
      return <Icons.tsx />
    case "md":
    case "mdx":
    case "markdown":
      return <Icons.md />
    case "sh":
    case "bash":
    case "shell":
    case "zsh":
      return <Icons.bash />
    case "py":
    case "python":
      return <Icons.python />
    case "go":
    case "golang":
      return <Icons.go />
    case "rs":
    case "rust":
      return <Icons.rust />
    default:
      return (
        <HugeiconsIcon
          icon={FileEmptyIcon}
          className="size-4 text-muted-foreground"
        />
      )
  }
}
